// EditorCommon: paths, logging and small reflection / asset helpers shared by the editor build scripts
// (MASTER_PROMPT 7.1: everything is regenerated by RebuildAll; no manual editor steps).
// Every log line starts with "[THREAD]" so the batch logs can be grepped by Tools/unity-queue.ps1.
using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;
using Object = UnityEngine.Object;

namespace Megastructure.EditorTools
{
