        public const string MaterialsDir = "Assets/_Game/Materials";
        public const string SettingsDir = "Assets/_Game/Settings";
        public const string ScenesDir = "Assets/_Game/Scenes";
        public const string ShadersDir = "Assets/_Game/Shaders";
        public const string GeneratedDir = "Assets/_Game/Shaders/Generated";
        public const string PaletteHlsl = "Assets/_Game/Shaders/Generated/ThreadPalette.hlsl";
        public const string ConstantsHlsl = "Assets/_Game/Shaders/Generated/ThreadConstantsGen.hlsl";
        public const string LibraryAsset = "Assets/_Game/Materials/MaterialLibrary.asset";
        public const string PaletteAsset = "Assets/_Game/Settings/ThreadPalette.asset";
        public const string LightingAsset = "Assets/_Game/Settings/ThreadLighting.lighting";
        public const string MainScene = "Assets/_Game/Scenes/Main.unity";
        public const string RpAsset = "Assets/Settings/PC_RPAsset.asset";
        public const string RendererAsset = "Assets/Settings/PC_Renderer.asset";
        public const string UrpGlobalSettings = "Assets/Settings/UniversalRenderPipelineGlobalSettings.asset";
        public const string DefaultVolumeProfile = "Assets/Settings/DefaultVolumeProfile.asset";
