    }

    /// <summary>"[THREAD] ..." logging; problems are collected so batch methods can exit non-zero.</summary>
    public static class ThreadLog
    {
        public const string Prefix = "[THREAD] ";

        public static void Info(string msg) => Debug.Log(Prefix + msg);
        public static void Warn(string msg) => Debug.LogWarning(Prefix + "WARNING " + msg);

        /// <summary>Logs an error and records it in the problem list (may be null).</summary>
        public static void Problem(List<string> problems, string msg)
        {
            Debug.LogError(Prefix + "ERROR " + msg);
            if (problems != null) problems.Add(msg);
        }

        /// <summary>Batch logs: no stack traces on plain log lines (keeps the logs readable).</summary>
        public static void QuietStackTraces()
        {
            Application.SetStackTraceLogType(LogType.Log, StackTraceLogType.None);
            Application.SetStackTraceLogType(LogType.Warning, StackTraceLogType.None);
        }
    }

    public static class EditorUtil
    {
        /// <summary>Resolves a type by full name across every loaded assembly (builders compile independently).</summary>
        public static Type FindType(string fullName)
        {
            var asms = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < asms.Length; i++)
            {
                Type t = null;
                try { t = asms[i].GetType(fullName, false); } catch { /* dynamic or broken assembly */ }
                if (t != null) return t;
            }
            return null;
        }

        /// <summary>Adds (or returns the existing) component of the named type; logs a problem if the type is missing.</summary>
        public static Component AddComponentByName(GameObject go, string fullName, List<string> problems)
        {
            var t = FindType(fullName);
            if (t == null || !typeof(Component).IsAssignableFrom(t))
            {
                ThreadLog.Problem(problems, $"scene: component type '{fullName}' not found (owner has not written it yet?) on '{go.name}'");
                return null;
            }
            var c = go.GetComponent(t);
            if (c == null) c = go.AddComponent(t);
            if (c == null) ThreadLog.Problem(problems, $"scene: AddComponent({fullName}) failed on '{go.name}'");
            return c;
        }

        /// <summary>Creates every missing folder of an asset path like "Assets/_Game/Materials".</summary>
        public static void EnsureFolder(string assetFolder)
        {
            assetFolder = assetFolder.TrimEnd('/');
            if (AssetDatabase.IsValidFolder(assetFolder)) return;
            int slash = assetFolder.LastIndexOf('/');
            string parent = assetFolder.Substring(0, slash);
            string leaf = assetFolder.Substring(slash + 1);
            EnsureFolder(parent);
            AssetDatabase.CreateFolder(parent, leaf);
        }

        /// <summary>The single object stored in a ProjectSettings/*.asset file (GraphicsSettings, TagManager, ...).</summary>
        public static Object LoadProjectSettingsObject(string projectSettingsPath)
        {
            var all = AssetDatabase.LoadAllAssetsAtPath(projectSettingsPath);
            return all != null && all.Length > 0 ? all[0] : null;
        }

        public static string AssetPathOf(Object o) => o != null ? AssetDatabase.GetAssetPath(o) : "";
    }
}
